interface Shape {
    public double area();
}

interface VolumeCalculable {
    public double volume();
}

public class Square implements Shape {
    private double length;

    public Square(double length) {
        this.length = length;
    }

    @Override
    public double area() {
        return length * length;
    }
}

public class Dice implements Shape, VolumeCalculable {
    private double length;

    public Dice(double length) {
        this.length = length;
    }

    @Override
    public double area() {
        return 6 * Math.pow(length, 2);
    }

    @Override
    public double volume() {
        return Math.pow(length, 3);
    }
}
